package com.learn.hub;

import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.ConfigurationPropertiesScan;
import org.springframework.context.annotation.Bean;
import org.springframework.core.env.Environment;

@SpringBootApplication
@ConfigurationPropertiesScan
public class JavaLearnHubApplication {

    public static void main(String[] args) {
        SpringApplication.run(JavaLearnHubApplication.class, args);
    }

    @Bean
    CommandLineRunner startupInfo(Environment env) {
        return args -> System.out.println(
                "profiles=" + String.join(",", env.getActiveProfiles())
                        + " port=" + env.getProperty("server.port", "8080"));
    }
}

package com.learn.hub.config;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.validation.annotation.Validated;

@Validated
@ConfigurationProperties(prefix = "learn-hub")
public record LearnHubProperties(
        @NotBlank String contentDir,
        @Min(1) @Max(100) int pageSize
) {

    public LearnHubProperties {
        if (pageSize == 0) {
            pageSize = 20;
        }
        if (contentDir == null || contentDir.isBlank()) {
            contentDir = "content";
        }
    }
}
